import{_ as r,o as a,c as o,a2 as d}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"全局违禁词","description":"灵萌全局违禁词配置：启用检测、处置策略、词库维护与命中统计。","frontmatter":{"title":"全局违禁词","description":"灵萌全局违禁词配置：启用检测、处置策略、词库维护与命中统计。"},"headers":[],"relativePath":"config/forbidden-words.md","filePath":"config/forbidden-words.md","lastUpdated":1785051348000}'),e={name:"config/forbidden-words.md"};function n(l,t,i,s,h,g){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="全局违禁词" tabindex="-1">全局违禁词 <a class="header-anchor" href="#全局违禁词" aria-label="Permalink to &quot;全局违禁词&quot;">​</a></h1><p>路径：<strong>系统设置 → 全局违禁词</strong></p><p>维护全站敏感词库，拦截或掩码用户发布的笔记、评论等内容。策略与词库保存在数据库，保存后引擎会自动重新加载。</p><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>账号具备违禁词相关权限（超级管理员，或在 <a href="/config/admin-permissions">账号权限</a> 中分配）</li><li>明确运营策略：是直接拒绝发布，还是掩码后放行、仅记录</li></ul><hr><h2 id="建议配置顺序" tabindex="-1">建议配置顺序 <a class="header-anchor" href="#建议配置顺序" aria-label="Permalink to &quot;建议配置顺序&quot;">​</a></h2><ol><li>展开 <strong>全局策略</strong> → 打开 <strong>启用检测</strong> → 选择默认处置 → <strong>保存全局策略</strong></li><li><strong>+ 新增违禁词</strong>，逐条或批量维护词库</li><li>上线后看 <strong>命中 TOP</strong> 与统计卡，微调误伤词条</li></ol><hr><h2 id="一、全局策略" tabindex="-1">一、全局策略 <a class="header-anchor" href="#一、全局策略" aria-label="Permalink to &quot;一、全局策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>启用检测</strong></td><td>关闭后引擎不再拦截内容</td></tr><tr><td><strong>默认处置</strong></td><td><strong>拒绝</strong>（reject）/ <strong>掩码</strong>（mask）/ <strong>仅记录</strong>（log_only）</td></tr><tr><td><strong>掩码字符</strong></td><td>选择掩码时用来替换的字符</td></tr><tr><td><strong>最短词长</strong></td><td>过短的匹配可忽略，减少误伤</td></tr></tbody></table><p>点 <strong>保存全局策略</strong> 后生效。</p><table tabindex="0"><thead><tr><th>默认处置</th><th>用户侧大致表现</th></tr></thead><tbody><tr><td>拒绝</td><td>提交失败，提示含敏感内容</td></tr><tr><td>掩码</td><td>敏感片段被替换后仍可发布（以业务接入为准）</td></tr><tr><td>仅记录</td><td>放行，但后台可看到命中统计</td></tr></tbody></table><hr><h2 id="二、词库维护" tabindex="-1">二、词库维护 <a class="header-anchor" href="#二、词库维护" aria-label="Permalink to &quot;二、词库维护&quot;">​</a></h2><ol><li>点 <strong>+ 新增违禁词</strong></li><li>填写： <ul><li><strong>违禁词</strong></li><li><strong>处置</strong>：可继承全局默认，或单独指定拒绝/掩码/仅记录</li><li><strong>启用</strong></li><li><strong>备注</strong>（可选，仅后台可见）</li></ul></li><li>保存</li></ol><p>列表可按 <strong>全部 / 启用 / 停用</strong> 筛选。单条可 <strong>编辑 / 清零（命中次数）/ 删除</strong>。</p><hr><h2 id="三、看数据" tabindex="-1">三、看数据 <a class="header-anchor" href="#三、看数据" aria-label="Permalink to &quot;三、看数据&quot;">​</a></h2><p>页面统计卡一般包括：词表合计、已启用词条、累计命中、有命中词条、检测策略等。</p><p><strong>命中 TOP（最多 10）</strong> 帮助发现：</p><ul><li>哪些词经常触发（可能要改文案引导）</li><li>哪些词误伤正常讨论（应停用或改处置）</li></ul><hr><h2 id="与区域笔记审核的关系" tabindex="-1">与区域笔记审核的关系 <a class="header-anchor" href="#与区域笔记审核的关系" aria-label="Permalink to &quot;与区域笔记审核的关系&quot;">​</a></h2><p>违禁词是<strong>全站内容安全底座</strong>；<strong>区域管理 → 笔记配置</strong> 里还有「先审后发 / 先发后审」等审核策略。</p><p>常见组合：</p><table tabindex="0"><thead><tr><th>目标</th><th>建议</th></tr></thead><tbody><tr><td>强管控</td><td>违禁词「拒绝」+ 笔记「先审后发」</td></tr><tr><td>宽松运营</td><td>违禁词「掩码」或「仅记录」+ 笔记「先发后审」</td></tr></tbody></table><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>加了词但不拦截</td><td>是否 <strong>启用检测</strong>；该词条是否启用；最短词长是否过大</td></tr><tr><td>正常词也被拦</td><td>检查词条是否过短/歧义；改为掩码或停用；看命中 TOP</td></tr><tr><td>保存后立刻不生效</td><td>刷新页面再试；确认保存成功提示</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/circle-note">圈子与笔记</a></li><li><a href="/config/system-settings">系统配置总览</a></li></ul>',34)])])}const u=r(e,[["render",n]]);export{c as __pageData,u as default};
